 1 | /* 🦙 Llama Player - Winamp Nostalgic Theme */
 2 | 
 3 | :root {
 4 |   --winamp-bg: #1a1a2e;
 5 |   --winamp-primary: #2d2d4a;
 6 |   --winamp-secondary: #3a3a5c;
 7 |   --winamp-accent: #00ff88;
 8 |   --winamp-accent-dim: #00aa55;
 9 |   --winamp-highlight: #ff6b9d;
10 |   --winamp-text: #e0e0e0;
11 |   --winamp-text-dim: #8888aa;
12 |   --winamp-border: #4a4a6a;
13 |   --winamp-progress-bg: #0d0d1a;
14 |   --winamp-progress-fill: linear-gradient(90deg, #00ff88, #00ccff);
15 |   --winamp-shadow: rgba(0, 0, 0, 0.6);
16 |   --font-mono: 'Courier New', monospace;
17 | }
18 | 
19 | * {
20 |   margin: 0;
21 |   padding: 0;
22 |   box-sizing: border-box;
23 | }
24 | 
25 | body {
26 |   font-family: var(--font-mono);
27 |   background: radial-gradient(ellipse at center, #1a1a2e 0%, #0a0a14 100%);
28 |   color: var(--winamp-text);
29 |   min-height: 100vh;
30 |   display: flex;
31 |   justify-content: center;
32 |   align-items: center;
33 | }
34 | 
35 | #root {
36 |   width: 100%;
37 |   max-width: 480px;
38 |   padding: 16px;
39 | }
40 | 
41 | /* Scrollbar estilo Winamp */
42 | ::-webkit-scrollbar {
43 |   width: 10px;
44 | }
45 | 
46 | ::-webkit-scrollbar-track {
47 |   background: var(--winamp-bg);
48 |   border-left: 1px solid var(--winamp-border);
49 | }
50 | 
51 | ::-webkit-scrollbar-thumb {
52 |   background: var(--winamp-primary);
53 |   border: 1px solid var(--winamp-border);
54 | }
55 | 
56 | ::-webkit-scrollbar-thumb:hover {
57 |   background: var(--winamp-secondary);
58 | }
59 | 
60 | /* Seleção de texto */
61 | ::selection {
62 |   background: var(--winamp-accent);
63 |   color: var(--winamp-bg);
64 | }
65 |
